#include "light_adc.h"
#include "oled.h"
#include "dht11.h"
#include "pwm_light.h"
#include "key.h"

#include <stdbool.h>
#include <stdio.h>
#include <stdint.h>


#if (1 == BSP_MULTICORE_PROJECT) && BSP_TZ_SECURE_BUILD
bsp_ipc_semaphore_handle_t g_core_start_semaphore =
{
    .semaphore_num = 0
};
#endif



/*******************************************************************************************************************//**
 * main() is generated by the RA Configuration editor and is used to generate threads if an RTOS is used.  This function
 * is called by main() when no RTOS is used.
 **********************************************************************************************************************/
void hal_entry(void)
{
    /* TODO: add your own code here */

    /* Wake up 2nd core if this is first core and we are inside a multicore project. */

        fsp_err_t error;

        uint32_t last_led_time = 0U;
        uint32_t last_print_time = 0U;

        dht11_data_t dht11_data;
        uint32_t last_dht11_time = 0U;

        uint32_t last_light_time = 0U;
        uint16_t light_average = 0U;

        uint32_t last_oled_time = 0U;
        bool auto_mode = false;
        dht11_data_t dht_data = {0U, 0U};

        bool dht_valid = false;

        uint32_t last_pwm_test_time = 0U;
        uint8_t test_pwm_percent = 0U;

        key_event_t key_event;
        uint32_t last_key_time = 0U;
        uint8_t pwm_percent = 0U;

        /*
         * 初始化 LED 模块。
         */
        led_init();

        /*
         * 初始化 UART9。
         */
        error = uart_debug_init();

        if (error != FSP_SUCCESS)
        {
            /*
             * UART 初始化失败时，让 LED 快速闪烁。
             * 这样即使串口不能输出，也能通过 LED 判断错误。
             */
            while (true)
            {
                led_toggle();

                R_BSP_SoftwareDelay(
                    100U,
                    BSP_DELAY_UNITS_MILLISECONDS
                );
            }
        }

        /*
         * 关闭 printf 缓冲，使数据立即发送。
         */
        setvbuf(
            stdout,
            NULL,
            _IONBF,
            0
        );

        printf(
            "\r\n"
            "UART9 init OK\r\n"
        );

        /*
         * 初始化 GPT0 1 ms 定时器。
         */
        error = timer_1ms_init();

        if (error != FSP_SUCCESS)
        {
            /*
             * GPT 初始化失败时，让 LED 慢速闪烁。
             */
            while (true)
            {
                led_toggle();

                R_BSP_SoftwareDelay(
                    500U,
                    BSP_DELAY_UNITS_MILLISECONDS
                );
            }
        }

        printf(
            "GPT0 1ms timer init OK\r\n"
        );


        /*
         * 初始化OLED
         */
        error = oled_init();

        if (error != FSP_SUCCESS)
        {
            printf(
                "OLED init failed: %ld\r\n",
                (long) error
            );

            while (true)
            {
                led_toggle();

                R_BSP_SoftwareDelay(
                    100U,
                    BSP_DELAY_UNITS_MILLISECONDS
                );
            }
        }

        /*
         * 只在启动时清屏一次。
         */
        error = oled_clear();

        if (error != FSP_SUCCESS)
        {
            printf(
                "OLED clear failed: %ld\r\n",
                (long) error
            );
        }

        //error = oled_show_startup();

        //if (error != FSP_SUCCESS)
       // {
        //    printf(
           //     "OLED display failed: %ld\r\n",
           //     (long) error
         //   );
       // }

        /*
         * 初始化温湿度传感器
         */
        error = dht11_init();

        if (error != FSP_SUCCESS)
        {
            printf(
                "DHT11 init failed: %ld\r\n",
                (long) error
            );

            while (true)
            {
                led_toggle();

                R_BSP_SoftwareDelay(
                    100U,
                    BSP_DELAY_UNITS_MILLISECONDS
                );
            }
        }

        printf("DHT11 init OK\r\n");
        /*
         * 初始化光敏传感器
         */
        error = light_adc_init();

        if (error != FSP_SUCCESS)
        {
            printf(
                "Light ADC init failed: %ld\r\n",
                (long) error
            );

            while (true)
            {
                led_toggle();
                R_BSP_SoftwareDelay(
                    200U,
                    BSP_DELAY_UNITS_MILLISECONDS
                );
            }
        }

        printf("Light ADC init OK\r\n");
        /*
         * 初始化PWM
         */
        error = pwm_light_init();

        if (error != FSP_SUCCESS)
        {
            printf(
                "PWM init failed: %ld\r\n",
                (long) error
            );

            while (true)
            {
                led_toggle();

                R_BSP_SoftwareDelay(
                    200U,
                    BSP_DELAY_UNITS_MILLISECONDS
                );
            }
        }

        printf("PWM init OK\r\n");

        key_init();

        printf("KEY module OK\r\n");

        /*
         * 主循环。
         */
        while (true)
        {
            uint32_t now = timer_1ms_get();

            /*
                * 每 10 ms 扫描按键。
                */
               if ((uint32_t)(now - last_key_time) >= 10U)
               {
                   last_key_time = now;

                   key_event = key_scan_10ms();

                   if (key_event == KEY_EVENT_INCREASE)
                   {
                       if (!auto_mode)
                       {
                           if (pwm_percent < 100U)
                           {
                               pwm_percent += 5U;
                           }

                           pwm_light_set_percent(
                               pwm_percent
                           );
                       }
                   }
                   else if (key_event == KEY_EVENT_DECREASE)
                   {
                       if (!auto_mode)
                       {
                           if (pwm_percent >= 5U)
                           {
                               pwm_percent -= 5U;
                           }
                           else
                           {
                               pwm_percent = 0U;
                           }

                           pwm_light_set_percent(
                               pwm_percent
                           );
                       }
                   }
                   else if (key_event == KEY_EVENT_MODE)
                   {
                       auto_mode = !auto_mode;
                   }
               }

               /*
                * 每 100 ms 读取光照。
                */
               if ((uint32_t)(now - last_light_time) >= 100U)
               {
                   last_light_time = now;

                   light_average = light_adc_read_average();
               }

               /*
                * 每 200 ms 更新 OLED。
                */
               if ((uint32_t)(now - last_oled_time) >= 200U)
               {
                   last_oled_time = now;

                   oled_show_control(
                       light_average,
                       pwm_percent,
                       auto_mode
                   );
               }

            if ((uint32_t)(now - last_led_time) >= 500U)
            {
                last_led_time = now;
                led_toggle();
            }

            if ((uint32_t)(now - last_print_time) >= 1000U)
            {
                last_print_time = now;

                printf(
                    "system tick = %lu ms\r\n",
                    (unsigned long) now
                );
            }

            if ((uint32_t)(now - last_dht11_time) >= 2000U)
            {
                last_dht11_time = now;

                error = dht11_read(
                    &dht11_data
                );

                if (error == FSP_SUCCESS)
                {
                    dht_valid = true;

                    printf(
                        "Temperature = %u C, Humidity = %u %%\r\n",
                        dht11_data.temperature,
                        dht11_data.humidity
                    );
                }
                else
                {
                    printf(
                        "DHT11 read failed: %ld\r\n",
                        (long) error
                    );
                }
            }
            if ((uint32_t)(now - last_light_time) >= 100U)
            {
                last_light_time = now;
                light_average = light_adc_read_average();

                printf(
                    "Light ADC average = %u / %u\r\n",
                    light_average,
                    (unsigned int) 4095U
                );
            }
            if ((uint32_t)(now - last_oled_time) >= 200U)
            {
                last_oled_time = now;

                error = oled_show_environment(
                    dht_valid,
                    dht11_data.temperature,
                    dht11_data.humidity,
                    light_average
                );

                if (error != FSP_SUCCESS)
                {
                    printf(
                        "OLED update failed: %ld\r\n",
                        (long) error
                    );
                }
            }
            if ((uint32_t)(now - last_pwm_test_time) >= 2000U)
            {
                last_pwm_test_time = now;

                error = pwm_light_set_percent(
                    test_pwm_percent
                );

                if (error == FSP_SUCCESS)
                {
                    printf(
                        "PWM duty = %u%%\r\n",
                        (unsigned int) test_pwm_percent
                    );
                }
                else
                {
                    printf(
                        "PWM set failed: %ld\r\n",
                        (long) error
                    );
                }

                test_pwm_percent += 25U;

                if (test_pwm_percent > 100U)
                {
                    test_pwm_percent = 0U;
                }
            }

        }
































#if (0 == _RA_CORE) && (1 == BSP_MULTICORE_PROJECT) && !BSP_TZ_NONSECURE_BUILD

#if BSP_TZ_SECURE_BUILD
    /* Take semaphore so 2nd core can clear it */
    R_BSP_IpcSemaphoreTake(&g_core_start_semaphore);
#endif

    R_BSP_SecondaryCoreStart();

#if BSP_TZ_SECURE_BUILD
    /* Wait for 2nd core to start and clear semaphore */
    while(FSP_ERR_IN_USE == R_BSP_IpcSemaphoreTake(&g_core_start_semaphore))
    {
        ;
    }
#endif
#endif

#if (1 == _RA_CORE) && (1 == BSP_MULTICORE_PROJECT) && BSP_TZ_SECURE_BUILD
    /* Signal to 1st core that 2nd core has started */
    R_BSP_IpcSemaphoreGive(&g_core_start_semaphore);
#endif

#if BSP_TZ_SECURE_BUILD
    /* Enter non-secure code */
    R_BSP_NonSecureEnter();
#endif
}

